"""Lower Sixth English Term One: original passages, written sound preparation and foundation extensions."""
import json
import re
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_en as B
from lessonlib import card,worked,learn,num,mcq
L.use_class("lower-sixth","Lower Sixth")
OUT=L.ROOT/"english"
SRC=["english"]
PATH=[]

def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)

def item(q,r,wrong,why):
    assert len(wrong)==3
    return dict(q=q,r=r,w=[x[0] for x in wrong],e=[x[1] for x in wrong],y=why)

def qa(n,key,level,items): return B.QA(f"el6-{n}-{key}",level,"{X.q}",items,SRC)

def choose(n,rows,level=2,key="apply"):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),why) for q,r,w,e,why in rows])

def word_order(n,sentences): return B.WO(f"el6-{n}-build",2,sentences,SRC)

def unit(n,title,goal,back,next_use,note,case,method,facts,applied,prereq=(),paper=None,extra=None,example=None):
    assert 4 <= len(facts) <= 6
    terms=[]; cases=[]
    for i,f in enumerate(facts):
        other=[x for j,x in enumerate(facts) if j!=i][:3]
        terms.append(item("Which term means "+f["meaning"]+"?",f["term"],[(x["term"],"That concerns "+x["meaning"]+", rather than "+f["meaning"]+".") for x in other],f["why"]))
        cases.append(item(f["case"]+"\nWhich description best fits the selected feature?",f["term"],[(x["term"],"That means "+x["meaning"]+". The selected feature instead illustrates "+f["meaning"]+".") for x in other],f["why"]))
    q0=qa(n,"terms",1,terms); q1=qa(n,"cases",1,cases)
    q3=extra or B.MT(f"el6-{n}-link",2,"Match each term to its example.",[(f["term"],f["case"]) for f in facts],SRC,pick=3)
    q4=B.SP(f"el6-{n}-repair",3,"Find the incorrect claim or language form.",[f["term"]+": "+f["meaning"]+"." for f in facts],[(f["error"],f["why"]) for f in facts],SRC)
    for st,f in zip(q4["pool"]["right"],facts): st["explain"]="This is correct: "+f["meaning"]+". Look for a claim that conflicts with a rule or distinction taught in Learn."
    questions=[q0,q1,applied,q3,q4]
    cards=[card(f"el6-{n}-c1","Distinguish the ideas used in this lesson.",[f["term"]+": "+f["meaning"]+"." for f in facts],q0["id"]),
       card(f"el6-{n}-c2","Read the whole example before identifying its function.",[f["case"] for f in facts],q1["id"]),
       card(f"el6-{n}-c3","A correction must preserve the intended meaning and form.",[f["error"]+" Correction: "+f["why"] for f in facts],q4["id"])]
    L.lesson("english","english-language",n,(f"el6-{n}",title),prereq,note,
       example or worked({},facts[0]["case"]+" Explain the selected feature.",[facts[0]["meaning"].capitalize()+".",facts[0]["why"]],facts[0]["term"]),cards,questions,paper=paper,
       learn=learn([("Your goal and connections","By the end, you should be able to "+goal+". Builds on: "+back+". Leads to: "+next_use+"."),
         ("Understand the pattern",note),("Read the original model",case),("Apply and check",method)],
         key_words=[(f["term"],f["meaning"]) for f in facts],mistake=(facts[0]["error"],facts[0]["term"]+": "+facts[0]["meaning"]+".",facts[0]["why"])))
    PATH.append((n,title,goal,back,next_use))

def writing(n,title,goal,back,next_use,note,model,method,facts,prompt,checks,prereq=()):
    unit(n,title,goal,back,next_use,note,'Original model extract: '+model[0],method,facts,
      word_order(n,[f['case'] for f in facts]),prereq,
      paper=dict(vars={},checks=[],prompt=prompt,model=model,checklist=checks))

def composition(n,title,goal,back,next_use,note,model,features,prompt,prereq):
    facts=[F(*row) for row in features]
    writing(n,title,goal,back,next_use,note,model,
      'Identify the audience, purpose and required content. Plan the order, draft in your own words and check each feature against the model. Explain why an edit improves the answer.',
      facts,prompt,[f['term'].capitalize()+': '+f['meaning']+'.' for f in facts]+['Use relevant original details and check sentence boundaries, agreement and spelling.'],prereq)

def adapt(n,source,title,goal,back,onward,prereq,case,application=None):
    """Explicit foundation extension; preserve validated patterns, revise local purpose."""
    obj=json.loads((L.ROOT.parent/'form-5/english'/f'{source}.json').read_text(encoding='utf-8'))
    obj=json.loads(json.dumps(obj,ensure_ascii=False).replace(f'e5-{source}',f'el6-{n}'))
    obj.update(lesson_no=n,**{'class':'Lower Sixth','subject':'english-language'},prerequisites=prereq)
    obj['skills'][0]['name']=title
    obj['learn']['sections'][0]['text']='By the end, you should be able to '+goal+'. Builds on: '+back+'. Leads to: '+onward+'.'
    obj['learn']['sections'][2]['text']=case
    if application: obj['questions'][2]=application
    L.write('english',n,obj);PATH.append((n,title,goal,back,onward))

unit(2,'Main ideas and supporting details','select a passage’s controlling idea and distinguish it from evidence or an unsupported claim','Form Five evidence-based reading','purpose, summary and inference',
 'A main idea states what the passage principally says about its topic. A topic names the subject but does not express the claim. Supporting details explain, illustrate or justify the main idea. A good main-idea statement covers the relevant details without adding a conclusion the passage does not support. It need not reproduce an opening sentence word for word.',
 'Original passage: The fictional school library changed its loan routine after pupils reported long queues. Volunteers sorted returns before the break, and borrowers placed requests on slips. The trial shortened some queues, but staff had not yet compared all weekdays. The passage describes a trial with a limited reported result, rather than proving every queue problem is solved.',
 'State the topic, ask what the writer says about it, then test a proposed main idea against the whole passage. Identify which detail supports it and which limitation it must retain.',[
 F('topic','the subject discussed without the full controlling claim','Library queues names the subject of the passage.','A topic label alone expresses every argument.','A main idea says something about the topic.'),
 F('main idea','the controlling point that accounts for the passage’s relevant details','A changed loan routine showed a limited improvement during a trial.','The passage proves every library needs identical slips.','The trial’s context and limited evidence must be preserved.'),
 F('supporting detail','information that develops or illustrates the controlling point','Volunteers sorted returns before the break.','A single detail is always the entire main idea.','A detail supports a broader point rather than necessarily replacing it.'),
 F('scope limit','a boundary on what the passage establishes','Staff had not compared all weekdays.','An early result guarantees permanent success.','The passage explicitly limits the comparison.')],choose(2,[
 ('Original passage: Bih’s club tested shaded seating. Members used it at midday, but rainy-day use was not recorded. Which main idea preserves scope?','A seating trial attracted midday use, with evidence still limited',['Rain never affects seating','Every school must build the same seats','Bih owns all the chairs'],['Rainy-day evidence is missing.','The trial does not establish a universal requirement.','Ownership is not stated.'],'Cover both the observed use and the evidence limit.'),
 ('Original passage: A fictional market team labelled separate collection bins and explained the labels. Sorting improved during observed mornings; afternoon use remains unknown. Which is the main idea?','A labelling-and-explanation trial improved observed sorting, with incomplete coverage',['The only topic is the colour of paper','All waste problems ended permanently','Afternoons were proved identical'],['The passage concerns a sorting intervention.','Only a limited observation is reported.','Afternoon use was not observed.'],'A main idea covers intervention, result and limitation.'),
 ('Original passage: Ayuk’s group shared a timetable to avoid room clashes. Reported clashes fell, though the group had no record of informal meetings. Which statement fits the whole passage?','A shared timetable reduced reported clashes but the record was incomplete',['Informal meetings never happen','The timetable is irrelevant','No meeting ever clashed again'],['Missing records do not prove absence.','The reported change concerns the timetable.','The claim exceeds the reported evidence.'],'Keep the central change without turning incomplete records into certainty.')]))

unit(3,'Audience, purpose and tone','justify an audience-and-purpose reading using specific language choices','main ideas and relevant details','text types and directed writing',
 'Audience is the intended reader or listener. Purpose is what the writer seeks to achieve, such as inform, request, persuade or entertain. Tone is the attitude conveyed through wording and structure. A text can have more than one purpose, but an interpretation needs evidence. Formal language does not automatically mean anger; a friendly tone does not prove the facts are reliable.',
 'Original notice to pupils: Please return borrowed equipment before the club closes so that the next group can prepare. Ask the organiser if you need more time. The request targets borrowers, gives a reason and offers a response. Its polite, practical tone differs from an insult or a claim that a penalty has already been imposed.',
 'Name the audience, identify the action or understanding sought and quote a short supporting phrase. Explain the tone through wording. Distinguish the author’s intention from proof that readers obeyed.',[
 F('audience','the people a text principally addresses','The equipment notice addresses borrowers.','Every text is written for exactly the same readers.','References and required actions identify likely readers.'),
 F('purpose','the result the writer seeks through the text','The notice asks readers to return equipment.','A request proves its action already happened.','Intended effect differs from observed response.'),
 F('tone','the attitude conveyed by language choices','Please and an offer of help create a polite practical tone.','Polite wording proves every statement is factually correct.','Tone and factual reliability are different judgements.'),
 F('language evidence','a particular phrase supporting an interpretation','Ask the organiser supports the reading that help is offered.','Tone should be guessed without looking at words.','Interpretation must be supported by textual choices.')],choose(3,[
 ('Original line to club members: Please suggest a suitable meeting time and explain your choice. Which purpose is best supported?','Requesting suggestions with reasons',['Announcing a meeting already completed','Insulting every member','Giving a final exam result'],['The line asks for future input.','Its polite request contains no insult.','No result is stated.'],'Please suggest and explain identify the intended action.'),
 ('Original appeal to readers: Support the reading corner; your donated books could widen its collection. Which interpretation is supported?','Persuading readers to contribute books',['Proving every reader already donated','Ordering a court judgement','Describing only a past holiday'],['An appeal is not evidence of compliance.','No legal judgement is involved.','The wording seeks a contribution.'],'The request and projected benefit support a persuasive purpose.'),
 ('Original message to a friend: I was relieved when your letter arrived. Which tone is supported by relieved?','Personal relief',['Unqualified hostility','A neutral list of measurements','Proof that all earlier worries were imaginary'],['Relieved conveys a different attitude.','The word expresses a personal feeling.','A feeling does not establish that previous concerns lacked basis.'],'Tie tone to the actual word without inventing background facts.')]),[2])

unit(4,'Recognising narrative, descriptive, expository and argumentative texts','identify a dominant text function and recognise mixed features','audience and purpose','summary and purposeful composition',
 'A narrative organises events; description creates a picture through selected detail; exposition explains a topic or process; argument advances a claim with reasons. These functions can overlap: a narrative may describe a setting, and an argument may explain background. Classify the dominant work done by the excerpt rather than spotting an isolated word and assuming the whole text has one pure form.',
 'Original models: Bih opened the hall, then discovered the missing key — narrative sequence. Dust lay along the narrow window ledge — description. A loan record links a borrower to an item — explanation. The club should retain loan records because they make returns traceable — argument. The same subject can support different text purposes.',
 'Ask what the passage mainly does: recount events, depict, explain or argue. Support the choice with a structural feature. A first-person pronoun alone does not determine the type.',[
 F('narrative','a text function organising events in time','Bih opened the hall, then searched for the missing key.','A narrative can never include a description.','Events can be developed alongside setting or character detail.'),
 F('description','a text function presenting selected qualities or impressions','Dust lay along the narrow window ledge.','Description must list every visible object.','Details are selected to create a relevant impression.'),
 F('exposition','a text function explaining a topic or process','A loan record links a borrower to an item.','Any explanation automatically argues for a disputed policy.','Explanation can clarify without advocating a policy.'),
 F('argument','a text function advancing a claim through reasons','The club should keep records because returns become traceable.','An unsupported opinion and a developed argument are identical.','Argument needs reasons and an intelligible relation to its claim.')],choose(4,[
 ('Original excerpt: A request enters the register, the organiser checks availability, and a reply confirms the booking. Its main function is to explain the process. Which category fits?','Expository',['Argumentative solely because it has verbs','Descriptive solely because it names an organiser','A poem proved by the commas'],['Verbs occur in many text types.','Naming a person does not establish description as dominant.','Punctuation does not prove verse.'],'The stated dominant function is process explanation.'),
 ('Original excerpt: The hall should stay open later because many pupils arrive after chores. Which dominant function is supported?','Argumentative',['Only a neutral physical description','Only a list with no claim','A narrative solely because pupils are mentioned'],['It advocates a policy with a reason.','Should and because connect claim and reason.','Mentioning people does not establish an event sequence.'],'Identify the proposal and its support.'),
 ('Original excerpt: The pale walls enclosed a cool, echoing room. The dominant function is what?','Descriptive',['An explicit policy argument','A complete sequence of several events','A set of transport calculations'],['No policy claim is advanced.','The line presents qualities rather than a sequence.','No quantities or calculations appear.'],'Selected sensory qualities build an impression.')]),[3])

unit(5,'Selecting essential information for summary','retain central points while removing repetition, illustration and unsupported additions','main ideas and text functions','inference and paraphrase',
 'A summary condenses a source for a stated focus. Select central information and necessary qualifications, combine related points and express them concisely. Examples and repetition can often be omitted, but a necessary contrast or limitation must remain. A summary should not add a personal recommendation or reverse uncertainty into certainty. Any word limit must come from the actual task.',
 'Original source: A fictional club moved notices to a sheltered board because rain damaged paper. Members also copied announcements into a book. The trial made notices easier to retain, but pupils absent from school still needed another way to receive them. Summary: Sheltered display and a record book improved retention of club notices, though reaching absent pupils remained unresolved.',
 'Identify the focus, mark central actions and results, then preserve any qualification needed to avoid distortion. Remove repeated examples before cutting essential meaning. Compare the summary against the source, not against what you wish had happened.',[
 F('essential point','information necessary to the source’s central meaning or task focus','The summary retains both improved retention and the unresolved access problem.','Every example is always essential.','Selection depends on the task and main meaning.'),
 F('compression','expressing relevant information more concisely','Related notice changes are combined in a short sentence.','Compression permits inventing a stronger outcome.','Shortening must preserve meaning.'),
 F('qualification','a limitation needed for accurate meaning','Absent pupils still need another communication route.','Every but clause can be deleted without changing meaning.','A contrast may carry a central limit.'),
 F('source fidelity','keeping a summary within the source’s meaning','No extra recommendation is added to the summary.','A summary should invent the writer’s preferred solution.','Source information and new advice are different tasks.')],choose(5,[
 ('Original source: The group labelled tools and recorded loans. Lost items were reported less often, but no independent count was made. Which summary is faithful?','Labelling and loan records coincided with fewer loss reports, without an independent count',['The trial proved no tool was ever lost','Every school must use identical labels','Independent counts confirmed a permanent result'],['Fewer reports do not prove no losses.','That recommendation is not supplied.','The source explicitly lacks independent counts.'],'Preserve both reported change and evidential limit.'),
 ('Original source: Bih offered morning and afternoon practice. Attendance was higher in the morning; reasons were not investigated. Which summary fits?','Morning practice had higher attendance, for reasons not investigated',['Pupils disliked all afternoon work','Morning practice guarantees better learning','The source proves household tasks caused absence'],['A preference or dislike is not established.','Attendance is not a learning-outcome measure.','No cause was investigated.'],'Condense the comparison without inventing its cause.'),
 ('Original source: A board displayed opening times twice in the same paragraph, then explained where to ask about changes. What can usually be compressed?','The repeated opening-time information',['The only instruction for finding updates','Every fact about access','An invented penalty for lateness'],['That instruction may be central to access.','Compression should retain relevant meaning.','A penalty is absent from the source.'],'Remove repetition before essential information.')]),[2,4])

unit(6,'Inference and conclusions from texts','justify a cautious inference and distinguish it from an unstated certainty','main ideas and summary fidelity','character interpretation and prose',
 'An inference combines textual clues with a reasonable connection. It is more than copying a sentence, but it must remain supported. Several explanations may fit the same clue, so the strength of the conclusion must match the evidence. Words such as may, suggests and probably can preserve appropriate uncertainty. An absence of information is not proof that an event never occurred.',
 'Original passage: Rain tapped the roof. Bih placed a basin under a damp patch and moved the books away. The passage suggests concern about water reaching the books. It does not state who owns the roof or prove that every book was damaged. The action supports an inference about precaution without establishing all background facts.',
 'Name the clue, explain the link and state the inference with suitable certainty. Test an alternative explanation. Reject an answer that adds a private motive or universal outcome without evidence.',[
 F('textual clue','a detail that supports an interpretation','Bih moves books away from a damp patch.','An inference needs no evidence from the passage.','The action provides a basis for interpretation.'),
 F('supported inference','a conclusion reasonably connected to supplied clues','Bih may be trying to protect books from water.','Concern about water proves every book is already ruined.','A precaution does not prove the feared damage happened.'),
 F('certainty limit','a restriction on how strongly evidence permits a claim','The passage does not identify the roof’s owner.','Missing ownership information proves nobody owns it.','Unstated information remains unknown.'),
 F('alternative explanation','another account compatible with the evidence','A cautious reader asks whether books were moved before damage occurred.','Only one possible motive can ever fit an action.','Evidence can leave more than one explanation open.')],choose(6,[
 ('Original passage: Ayuk checked the clouds and placed a cover over the seed trays. Which inference is supported?','He may be protecting the trays from expected weather',['He certainly knows tomorrow’s rainfall total','Every tray was already destroyed','He owns every farm nearby'],['No exact forecast is supplied.','Precaution does not establish destruction.','Ownership beyond the trays is not stated.'],'Cloud checking and a cover support a weather precaution.'),
 ('Original passage: Before speaking, Bih read her notes again and took a slow breath. Which conclusion respects the evidence?','She appears to be preparing carefully',['She definitely forgot every word','She must dislike all listeners','The speech has already failed'],['Reading notes does not prove total forgetting.','No hostility towards listeners is stated.','No outcome has occurred in the excerpt.'],'The actions support preparation, not invented certainty about feelings or outcomes.'),
 ('Original passage: The hall was dark when the group arrived. Nothing else is said. What remains uncertain?','Why the hall was dark',['Whether the passage mentions darkness','Whether the group arrived','Whether darkness is described'],['Darkness is directly stated.','Arrival is directly stated.','The text explicitly describes that condition.'],'A condition alone does not identify its cause.')]),[5])

unit(7,'Prose: character and setting','explain how an original prose passage presents character through action and setting','evidence-based inference','creative narrative and drama comparison',
 'Prose uses sentences and paragraphs rather than requiring verse lines. Fictional character can be presented directly through description or indirectly through speech, action and others’ responses. Setting includes place, time and social conditions; it can create obstacles and shape choices. A narrator’s viewpoint is not automatically the author’s personal belief. An interpretation should cite a detail and explain its effect.',
 'Original passage: At the crowded bus shelter, Ngozi kept her folder beneath her jacket. A stranger’s papers scattered into the puddles. She hesitated, shifted her own folder under a dry bench, then knelt to help. The wet crowded setting creates a practical conflict. Her sequence of actions suggests concern for both her own work and another person, without proving an unchanging trait in every situation.',
 'Identify a setting detail, a character action and their connection. Explain what the sequence suggests and what remains uncertain. Use this original passage for foundations; no prescribed novel is substituted.',[
 F('characterisation','the presentation of a fictional person through detail and behaviour','Ngozi secures her folder, then helps the stranger.','An action proves the character acts identically forever.','Character interpretation must match the particular evidence.'),
 F('setting','the place, time and conditions of a story','A wet crowded bus shelter constrains movement.','Setting can never affect a character’s choices.','Conditions can create obstacles and opportunities.'),
 F('narrative viewpoint','the position from which events are presented','The narrator describes Ngozi’s observable hesitation.','Every narrator is identical to the real author.','A constructed voice and its author are distinct.'),
 F('interpretive evidence','a textual detail linked to a claim about meaning','Helping after securing her own folder supports a qualified reading.','A character label needs no quoted or described action.','Evidence connects a reading to the passage.')],choose(7,[
 ('Original prose: Tabe gave his dry seat to a traveller but kept a place for his bag. Which reading is best supported?','He offers help while still attending to his belongings',['He always rejects every traveller','He has no belongings','He is proved generous in every event of his life'],['The offered seat contradicts total rejection.','The bag is mentioned.','One scene does not prove every future action.'],'Read both actions and limit the conclusion.'),
 ('Original prose: The narrow bridge made the group cross in single file. What does the setting do?','Constrains how the characters move',['Proves the narrator built the bridge','Shows every character has the same motive','Removes every obstacle'],['The builder is not identified.','Motives are not supplied.','The narrowness creates a constraint.'],'Connect physical detail with its effect on the action.'),
 ('Original prose: I thought the locked door was a warning, though I had not asked the caretaker. What should a reader distinguish?','The narrator’s interpretation from an established explanation',['A proven statement by the caretaker','Proof the door was never locked','The real author’s confirmed intention'],['The caretaker has not been asked.','The lock is part of the narrated observation.','The narrator’s belief does not establish authorial intention.'],'A first-person account can reveal a limited viewpoint.')]),[6])

unit(8,'Written sound preparation: English monophthongs','match selected vowel symbols to model words and explain the limits of a written exercise','Form Five sound-symbol contrasts','oral practice and homophone distinctions',
 'A monophthong is conventionally represented as a single vowel quality, unlike a diphthong’s movement between qualities. Phonemic symbols describe a target pronunciation, not spelling letters. In the selected British dictionary model, compare /iː/ in sheep with /ɪ/ in ship, /e/ in bed with /æ/ in cat, and /ʊ/ in put with /uː/ in food. Quality matters as well as duration. English varieties differ; this page supplies written preparation, not audio assessment.',
 'Written model key: sheep /iː/, ship /ɪ/, bed /e/, cat /æ/, father /ɑː/, hot /ɒ/, law /ɔː/, put /ʊ/, food /uː/, cup /ʌ/, bird /ɜː/, the final vowel of sofa /ə/. The key states the chosen teaching model, not a judgement that every local accent must sound identical. Schwa is common in unstressed syllables. Ask a teacher to demonstrate and check listening and production separately.',
 'Use the supplied model key to compare symbols and words. Do not infer a vowel sound from a letter alone. A screen choice demonstrates symbol knowledge; it does not demonstrate hearing or pronunciation. Use teacher-led listening and speaking for those skills.',[
 F('monophthong','a vowel conventionally represented with a single quality','The key represents ship with /ɪ/.','Every written vowel letter always identifies a single sound.','Spelling letters and vowel sounds are different systems.'),
 F('phonemic symbol','a sign representing a sound distinction in a selected pronunciation model','The key distinguishes /iː/ and /ɪ/.','The written words sheep and ship have identical target vowels here.','The stated key represents a vowel contrast.'),
 F('schwa','the vowel represented by /ə/, often in unstressed syllables','The model key gives sofa’s final vowel as /ə/.','Schwa must always be the stressed vowel of a word.','Schwa commonly occurs without stress in the chosen model.'),
 F('written preparation','symbol and example study before actual listening and production','A pupil matches /ʊ/ to put using the printed key.','A correct screen choice proves accurate pronunciation.','Reading a symbol does not assess the produced sound.')],choose(8,[
 ('Use the printed British-model key. Which pair contrasts /iː/ and /ɪ/?','sheep / ship',['bed / cat','put / food','cup / bird'],['That key pair contrasts /e/ and /æ/.','That key pair contrasts /ʊ/ and /uː/.','That key pair contrasts /ʌ/ and /ɜː/.'],'Read the stated sound model rather than guessing from letters.'),
 ('Use the printed key. Which word illustrates /ʊ/?','put',['food','cat','sheep'],['Food illustrates /uː/ here.','Cat illustrates /æ/ here.','Sheep illustrates /iː/ here.'],'The key distinguishes put from food.'),
 ('Use the printed key. What is the final vowel shown for sofa?','/ə/',['/æ/','/ɪ/','/ɔː/'],['The model assigns /æ/ to cat.','The model assigns /ɪ/ to ship.','The model assigns /ɔː/ to law.'],'The unstressed final model vowel is schwa.'),
 ('Use the printed key. Which word illustrates /e/?','bed',['cat','bird','hot'],['Cat illustrates /æ/.','Bird illustrates /ɜː/.','Hot illustrates /ɒ/.'],'The supplied key gives bed as the /e/ model.')]),[7])

adapt(9,32,'Formal and informal letters: purpose and register','write to a specified recipient with suitable register, a clear request and relevant support','audience, purpose and prior letter layouts','essay structure and directed writing',[3,4],
 'Lower Sixth extension: compare a formal request to a school coordinator with a personal letter explaining the same club proposal to a friend. Preserve the facts while changing salutation, explanation and tone for each recipient. State what response is sought. A formal style is not an excuse for inflated or insulting language. The model pair and paper task below extend the Form Five letter foundation; teachers should confirm the required examination layout.')

unit(10,'Nouns, pronouns and verbs in context','identify a word’s function in its sentence and maintain clear reference','Form Five parts of speech','modification, determiners and sentence control',
 'A noun can head a noun phrase; a pronoun can stand as the head of a noun phrase and refer to a person, thing or idea. A verb heads the predicate and can express an action, event or state. Form alone is insufficient: record is a noun in the record and a verb in record the decision. Pronoun references need to be clear. A sentence can contain several verb forms with different functions.',
 'Original model: Bih keeps the club record. She records decisions after meetings. Record follows the and heads a noun phrase in the first sentence; records is the finite verb in the second. She refers to Bih. If another possible person intervenes, repeating a name may be clearer than leaving a pronoun ambiguous.',
 'Locate the whole phrase and clause before labelling a word. Ask what it does here. Track the intended referent and test whether a reader could reasonably identify someone else.',[
 F('noun use','a word functioning as the head of a noun phrase','The record is complete uses record as a noun.','Record must be the same word class in every sentence.','Sentence position and function distinguish its uses.'),
 F('pronoun reference','the link between a pronoun and the person or thing identified','Bih checked the record; she corrected it.','A pronoun can never be unclear.','Several possible referents can create ambiguity.'),
 F('finite verb','a verb form carrying tense or agreement in its clause','Bih records decisions has records as its finite verb.','Every word ending in s is a plural noun.','Records functions as a verb in this clause.'),
 F('state verb use','a verb expressing a condition rather than an action here','The record seems complete uses seems for a state.','Every verb must describe a physical action.','Verbs can express states as well as actions.')],choose(10,[
 ('In The club will record the decision, what is record doing?','Functioning as a verb after will',['Heading a noun phrase after the','Replacing the club as a pronoun','Describing a noun as an adjective'],['It follows the auxiliary will, not the determiner the.','It does not replace a referent.','It names the predicated action.'],'Function in the clause determines the label.'),
 ('Bih told Ngozi that she had the key. Without further context, what may need clarification?','Who she refers to',['Whether key is mentioned','Whether Bih spoke to Ngozi','Whether the sentence has any verb'],['Key is explicit.','That relationship is explicit.','Told and had are verb forms.'],'Both named people could be possible referents.'),
 ('In The room seems quiet, why is seems a verb?','It heads a predicate expressing a state',['Only action words can ever be verbs','It is the name of the room','Every word before an adjective is a noun'],['Verbs can express states.','Room names the place.','Position alone does not justify that rule.'],'A state can be predicated without physical movement.')]),[9])

adapt(11,7,'Essay structure: a focused and developed line of thought','plan and draft an essay whose paragraphs develop its stated purpose','text types, summary selection and earlier essay structure','creative writing and later argument',[4,5],
 'Lower Sixth extension: compare a topic label with a defensible direction for an essay. Reading spaces is a subject; the claim that access depends on opening times as well as furniture gives a line to develop. Each paragraph needs a relevant point, explanation and evidence or example. A conclusion should follow the reasoning without inventing a new survey result. The model and paper task extend the Form Five structure foundation.')

unit(12,'Adjectives, adverbs, prepositions and conjunctions','identify modifiers and connectors from their function in context','nouns, pronouns and verbs','paraphrase and sentence relationships',
 'Adjectives typically modify nouns or serve as complements, as in a quiet room or the room is quiet. Adverbs can modify verbs, adjectives, other adverbs or clauses. Prepositions head phrases linking a complement, as in near the library. Conjunctions connect words, phrases or clauses. A word’s function depends on its sentence: fast can be adjectival or adverbial without an added ending.',
 'Original models: The careful reader checked the note carefully. The note lay beside the register. Bih stayed because a member needed help. Careful modifies reader; carefully modifies checked; beside heads a phrase with the register; because introduces a reason clause. Identifying functions helps explain why an edit changes meaning.',
 'Underline the word being modified or the units being connected. Do not label every word ending in ly as an adverb without reading its use. Explain what relationship a connector expresses.',[
 F('adjective function','modification of a noun or description as a complement','Careful modifies reader in the careful reader.','Careful and carefully have identical functions in every sentence.','Forms must suit their role in the sentence.'),
 F('adverb function','modification of a verb, adjective, adverb or clause','Carefully tells how the reader checked.','Every modifier of a verb must be an adjective.','An adverb can describe how an action is performed.'),
 F('preposition function','heading a phrase with a complement to express a relationship','Beside the register locates the note.','Beside is the finite verb in this phrase.','The phrase expresses location rather than a finite action.'),
 F('conjunction function','connection of words, phrases or clauses','Because introduces the reason for staying.','Because and although always express the same relationship.','Reason and concession are different connections.')],choose(12,[
 ('Choose the form modifying checked: Bih checked the entry ___.','carefully',['careful','carefulness','care'],['Careful normally modifies a noun or acts as a complement.','Carefulness is a noun.','Care does not provide the required manner modifier here.'],'The adverb modifies the checking action.'),
 ('In The folder is under the bench, what does under the bench do?','Expresses a location relationship through a prepositional phrase',['Names the finite verb','Introduces a reason clause','Counts the folders'],['Is is the finite verb.','No reason clause follows under.','The phrase gives location, not quantity.'],'Under heads a phrase with the bench as complement.'),
 ('Choose the connector for the stated reason: Bih stayed ___ a pupil needed help.','because',['although','unless','despite'],['Although introduces concession, not the requested reason.','Unless introduces a condition.','Despite needs a different complement pattern here.'],'Because connects the action to its reason.')]),[10,11])

unit(13,'Paraphrasing without changing meaning','restate an idea with changed wording and structure while preserving scope','summary fidelity and word functions','accurate directed writing and vocabulary',
 'Paraphrasing restates a source’s meaning using a different structure and wording. It is not a sequence of unrelated synonyms, and it must retain who did what, the time, causation and any qualification. Technical terms may need to remain. A paraphrase of someone else’s idea still needs acknowledgement where the task requires it; changed wording does not turn the idea into your discovery.',
 'Original source: Some members could not attend because the meeting ended after the last available bus. Faithful paraphrase: The meeting’s late finish prevented certain members from attending, given the available bus service. Some must not become all, and a transport constraint must not become a claim that members lacked interest. This is an invented practice source, not an actual attendance report.',
 'First explain the idea without looking at the wording, then compare your version with the original. Check actor, quantity, time, reason and certainty. Keep a necessary term rather than choosing a near-synonym that changes the claim.',[
 F('meaning preservation','retaining the source’s core relationships and scope','Some members becomes certain members, not every member.','Paraphrasing permits changing some to all.','Quantity changes can distort the claim.'),
 F('structural change','expressing an idea through a different sentence pattern','A because clause can become an appropriate causal phrase.','A paraphrase must copy the original syntax exactly.','A new structure can express the same relationship.'),
 F('qualification retention','keeping limits such as possibility or partial coverage','May improve remains a possibility rather than a proven result.','May and certainly always express equal certainty.','Changing certainty changes meaning.'),
 F('acknowledgement','recognition of another source’s idea when required','A researched essay identifies where an adopted idea came from.','Changing words makes every borrowed idea your own discovery.','Authorship of wording and origin of an idea differ.')],choose(13,[
 ('Paraphrase faithfully: The trial may reduce queues.','The trial could make queues shorter.',['The trial certainly ended every queue','Queues caused the trial to fail','No trial was held'],['May does not establish certainty or universality.','The source does not state that causal reversal.','The existence of a trial is supplied.'],'Retain possibility and the intended effect.'),
 ('Paraphrase faithfully: Only registered members may borrow the folders.','Borrowing the folders is restricted to registered members.',['Anyone may borrow without registering','Registered members must borrow every folder','No registered member may borrow'],['Only restricts eligibility.','Permission does not create an obligation.','That reverses the permission.'],'Preserve the eligibility restriction and permission.'),
 ('Paraphrase faithfully: Bih delayed the meeting because the room was unavailable.','The room’s unavailability caused Bih to postpone the meeting.',['Bih cancelled every future meeting','The meeting made all rooms unavailable','Bih delayed it because she disliked the members'],['A delay is not permanent cancellation.','That reverses the stated cause.','The proposed motive is invented.'],'Keep actor, action and cause.')]),[5,12])

unit(14,'Determiners: articles, quantity and possession','choose a determiner that fits reference, countability and meaning','noun phrases and prior quantifiers','precise description and summary',
 'Determiners help specify a noun phrase. Articles distinguish uses such as a new proposal and the proposal already identified. The choice of a or an follows the next sound in the selected pronunciation, not simply its first letter: an hour but a useful guide. Quantifiers express amount or number; possessive forms identify a relationship. Countability depends on use: information is uncountable in the model, while an item of information is countable.',
 'Original model: Bih read a proposal. The proposal concerned our library and requested some information. A introduces an unspecified proposal; the points back to the identified one; our marks a relationship; some fits the uncountable use of information. These choices guide the reader’s reference rather than merely decorating the noun.',
 'Identify the noun and intended reference. Test countability in this use, the next sound for a/an and whether possession or quantity is intended. Do not combine incompatible determiners merely because each can occur elsewhere.',[
 F('indefinite article','a or an introducing a singular countable noun phrase in the taught use','A proposal introduces a not-yet-identified proposal.','An must precede every word beginning with a vowel letter.','The next sound, rather than the letter alone, determines a or an.'),
 F('definite article','the used for an identifiable referent in the taught context','The proposal points back to the one just introduced.','The always means the referent is unknown to everyone.','Context can identify a referent.'),
 F('quantity determiner','an expression specifying amount or number','Some information refers to an uncountable amount here.','Many information is the taught ordinary pattern.','Many fits plural countable nouns, not this use of information.'),
 F('possessive determiner','a form such as our specifying a possessive relationship before a noun','Our library relates the library to the group.','Our and ours are interchangeable before library.','Our precedes the noun; ours can stand independently.')],choose(14,[
 ('Choose the model article: ___ hour remained.','An',['A','Many','Ours'],['Hour begins with a vowel sound in this model.','Hour is singular here.','Ours cannot determine hour this way.'],'The article follows sound, not the silent initial letter.'),
 ('Choose the model article: It is ___ useful guide.','a',['an','many','ours'],['Useful begins with a consonant /j/ sound in this model.','Guide is singular here.','Ours does not determine guide this way.'],'Use a before the consonant onset in useful.'),
 ('Choose the ordinary uncountable pattern: We need ___.','some information',['an information','many information','a few information'],['Use an item of information for a countable unit.','Many normally requires a plural countable noun.','A few requires plural countable items.'],'Match the quantity form to the noun’s use.'),
 ('Bih read a report. ___ report proposed a library trial. Choose the reference back to the same report.','The',['An','Many','Ours'],['Report starts with a consonant sound and the referent is already identified.','Report is singular here.','Ours does not determine report this way.'],'The points back to the identified report.')]),[10,13])

composition(15,'Creative writing: purposeful invention','draft an original scene whose viewpoint, details and choices create a coherent effect','character, setting and essay organisation','drama and narrative reconstruction',
 'Creative writing makes purposeful choices about viewpoint, situation, voice and detail. Imagination does not require an impossible event; an ordinary choice can create interest when its stakes are clear. Select details that contribute to the scene, let actions reveal character and give the reader enough continuity to follow. A surprising ending should connect to earlier events rather than solve everything through an unexplained intervention.',
 ['The envelope lay beneath the library door. I recognised the club stamp, but the name on the front belonged to a pupil who had left. Beside me, Bih reached for it. I held my hand above the paper and stopped.',
 '“We should ask the organiser,” I said. Bih looked at the rain creeping across the floor. She fetched an empty tray, and we lifted the envelope without opening it. When the organiser arrived, the paper was dry and the seal remained unbroken.'],[
 ('consistent viewpoint','a stable perspective through which the scene is presented','I recognised the stamp presents a first-person viewpoint.','A narrator must know every character’s private thought.','A limited viewpoint need not supply information it cannot know.'),
 ('relevant detail','a selected feature contributing to mood, action or meaning','Rain creeping across the floor creates urgency.','Every imaginable object must be described.','Select details that help the intended effect.'),
 ('character choice','an action that reveals priorities under a constraint','The pupils protect the envelope without opening it.','A character is developed only by a list of adjectives.','Choices and actions can reveal priorities.'),
 ('coherent consequence','a result connected to the scene’s earlier actions','The envelope stays dry because the pupils use a tray.','An unexplained event is always the strongest resolution.','Consequences should follow intelligibly from the established situation.')],
 'Write an original scene about finding an object intended for someone else. Establish a viewpoint, a meaningful constraint and a choice with a consequence. Do not copy the envelope model; change the situation and language.',[7,11,14])

adapt(17,29,'Word formation: bases, prefixes and suffixes','analyse an affixed word in context and distinguish formation from a guessed letter sequence','word functions and paraphrase','lexical relations and precise word choice',[12,13,15],
 'Lower Sixth extension: analyse how a base, prefix or suffix affects meaning and grammatical use in a sentence. Compare happy, unhappy and happiness without assuming every apparent beginning is a productive prefix. Check an unfamiliar formation in a suitable dictionary rather than inventing a form. A related word may change function, so test its sentence role as well as its spelling. The pattern banks extend the Form Five word-formation foundation.')

unit(18,'Drama: plot, conflict and stage evidence','explain a dramatic conflict using dialogue, stage directions and changing action','prose characterisation and creative scenes','narrative reconstruction and later drama analysis',
 'Drama presents action for performance through dialogue and stage directions. Plot is the organised development of action; conflict is a clash of aims, obligations or forces that drives choices. Conflict can occur within a character as well as between people. Stage directions can shape movement, pauses and audience knowledge. A character’s spoken claim is not automatically a fact endorsed by the playwright.',
 'Original scene: [At a locked hall. Bih holds a notice; Tabe carries chairs.] Bih: The notice says our group booked this room. Tabe: The organiser gave us the same time. [They compare the notices.] Bih: Let us ask before moving anything. The competing bookings create the conflict. Comparing notices changes the action from assertion towards checking evidence. No prescribed play is being replaced by this invented scene.',
 'Identify each aim and the obstacle. Cite dialogue or a stage direction, then explain how it moves the action. Distinguish an assertion, an observed action and a possible performance choice.',[
 F('dialogue','words spoken by dramatic characters','Bih says the notice gives her group a booking.','Everything a character says is proved true by being spoken.','Speech can express a claim, misunderstanding or intention.'),
 F('stage direction','written guidance for action or presentation in performance','They compare the notices directs an observable action.','Stage directions must always be spoken aloud by characters.','They guide performance rather than necessarily belonging to dialogue.'),
 F('conflict','a clash of aims or pressures motivating action','The groups appear to have competing room bookings.','Conflict must always involve physical violence.','Competing aims can drive a non-violent dramatic conflict.'),
 F('plot development','an organised change in action or situation','Comparing the notices moves the scene towards verification.','Plot is only a list of unrelated character names.','Action develops through connected events and choices.')],choose(18,[
 ('Original scene: [Ngozi hides a damaged cup.] Ngozi: Nothing happened. What should a reader distinguish?','The spoken denial from the action supplied by the stage direction',['The denial as proof no cup exists','The playwright’s confirmed personal opinion','A stage direction that must be shouted'],['The direction explicitly mentions a damaged cup.','A character’s denial is not the author’s belief.','Directions guide performance, not automatic speech.'],'The audience can know something different from the spoken claim.'),
 ('Original scene: Ayuk wants to disclose a mistake but fears losing the club’s trust. What conflict is shown?','An internal conflict between competing pressures',['Only a physical battle','No conflict because only one person is named','A proven legal judgement'],['No battle is described.','A character can experience internal conflict.','No court or ruling is stated.'],'Drama can develop an inward dilemma.'),
 ('Original scene: [Bih reads the notice again, then hands it to Tabe.] How can this direction affect the scene?','It stages a pause and a shared look at evidence',['It proves every booking issue is resolved','It removes the need for any actor','It makes the notice’s contents automatically false'],['Checking is not a final resolution.','The action still requires performance.','Reading and sharing do not establish falsity.'],'Explain the action’s effect without inventing an outcome.')]),[7,15,17])

unit(19,'Synonyms, antonyms, homonyms and homophones','choose a lexical relationship in context and preserve meaning when substituting','word formation and model sound contrasts','narrative retelling and confusing words',
 'Synonyms have similar meanings in an appropriate context, but are not interchangeable in every phrase. Antonyms express opposition along a relevant dimension. Homophones share pronunciation in the selected model while differing in meaning and often spelling. Homonym terminology varies: here a homonym shares spelling and pronunciation but has distinct unrelated meanings. State the convention and use the sentence to distinguish senses.',
 'Original models: a rapid response and a quick response are close in this context. Open contrasts with closed for the door’s state. Flour and flower are model homophones; a bat used in a game and a bat as an animal illustrate our narrow homonym convention. Sound patterns can vary by accent, while context still helps identify intended meaning.',
 'Identify the meanings in their actual sentences. Test a replacement for sense, register and collocation. For sound relationships use the stated model and seek oral demonstration; a printed choice alone is not listening assessment.',[
 F('contextual synonym','a word with a similar meaning in the specified use','Quick can replace rapid in a rapid response.','Every synonym works in every phrase and register.','Meaning and collocation depend on context.'),
 F('antonym','a word expressing a relevant opposition','Closed contrasts with open for this door state.','Any unrelated word is an antonym.','Opposition needs a shared dimension.'),
 F('homophone','a word sharing pronunciation with another in the selected model','Flour and flower share the model pronunciation.','Different spelling always guarantees different sound.','Spelling and pronunciation do not correspond uniquely.'),
 F('homonym in this lesson','a word sharing spelling and pronunciation with an unrelated meaning','Bat names an animal or a game implement in these examples.','The lesson’s narrow homonym convention must be universal.','Dictionaries and courses can use broader terminology.')],choose(19,[
 ('In a rapid response, which replacement is close in meaning?','a quick response',['an absent response','a hostile response','a response made of water'],['Absent changes presence rather than speed.','Hostile changes attitude rather than speed.','That phrase does not preserve the intended sense.'],'The relevant dimension is speed.'),
 ('The room was open, not ___. Choose the direct state contrast.','closed',['blue','quiet','large'],['Colour is a different dimension.','Noise is a different dimension.','Size is a different dimension.'],'Antonyms contrast along the relevant meaning dimension.'),
 ('In the supplied pronunciation model, flour and flower sound alike but have different meanings. Which relationship is shown?','Homophony',['Antonymy','A prefix relationship','Identical spelling'],['Their meanings are not opposites.','Neither is formed by prefixing the other.','Their spellings differ.'],'Shared model pronunciation identifies homophones.'),
 ('A bat flew above the pitch; a player held a bat. Under this lesson’s narrow convention, what is illustrated?','Homonymy',['Antonymy','Two words with different spellings','A common suffix'],['Animal and implement are not opposite ends of a scale.','Both uses are spelled bat.','No suffix relationship is described.'],'The form is shared while the contextual meanings differ.')]),[8,17,18])

unit(20,'Retelling texts in a coherent sequence','reconstruct events while preserving order, causes and the source’s limits','narrative features and lexical precision','word choice and narrative composition',
 'Retelling reorganises a source into a clear account of its events while keeping their relationships. Distinguish the order in which events happened from the order in which a narrator revealed them. Before, after and because express different relations: succession alone does not prove cause. A retelling can compress details but should retain a turning point and not invent dialogue, motives or an outcome.',
 'Original source: When the group arrived, the hall was locked. They checked their notice and called the organiser. Only after the organiser confirmed a different room did they move the chairs. Retelling: The locked hall prompted the group to check its notice and seek clarification; following confirmation, it moved to another room. The account must not say they forced entry or moved before confirmation.',
 'List events with time clues. Mark causes only where supported. Retell with clear references and consistent tense, then compare every action against the source. If the source leaves a result unknown, retain that limit.',[
 F('chronological order','the sequence in which events occur','The group checks before moving to the confirmed room.','After and before express the same order.','Time connectors determine different event relationships.'),
 F('causal relation','a supported link explaining why something happened','The locked hall prompts a check in the model.','Any earlier event must cause every later event.','Time order alone does not establish causation.'),
 F('turning point','an event changing the direction of the account','Confirmation of another room changes the group’s action.','A retelling should omit every consequential change.','The source’s important change helps explain what follows.'),
 F('faithful retelling','a reordered or condensed account preserving the source’s meaning','The retelling does not invent forced entry.','Inventing dialogue is always permitted in a factual retelling.','Unstated additions must not be presented as source events.')],choose(20,[
 ('Original source: Bih found the note after the meeting had ended. Which event came earlier?','The meeting ended',['Bih found the note','Both are stated to be simultaneous','The text supplies no time relationship'],['After places the finding later.','The connector does not indicate simultaneity.','After supplies a relative order.'],'Read the stated temporal relation.'),
 ('Original source: Ayuk checked the address before posting the letter. Which retelling preserves order?','He verified the address, then posted the letter',['He posted it, then checked the address','He never posted the letter','He checked every letter in the town'],['That reverses before.','The source includes posting.','That adds an unsupported universal action.'],'Keep the check before the posting.'),
 ('Original source: Rain began; later the lights failed. No cause is supplied. Which retelling respects the evidence?','Rain began before the lights failed; the cause is not stated',['Rain is proved to have caused the failure','The lights failed before rain began','The source proves no other cause is possible'],['Sequence alone does not prove causation.','That reverses the order.','Other explanations are not excluded.'],'Preserve sequence without inventing a cause.')]),[18,19],extra=B.WO('el6-20-sequence',2,['First check the notice, then contact the organiser.','After confirmation arrived, the group moved the chairs.','Before posting the letter, Ayuk checked the address.','Once the room was confirmed, Bih informed the members.'],SRC))

unit(21,'Malapropism and words often confused','repair a contextually wrong near-sounding word and explain the intended meaning','lexical relationships and retelling','accurate narrative and editing',
 'A malapropism substitutes an inappropriate word resembling the intended word in sound, often creating an unintended comic effect. Not every spelling error or joke is a malapropism. Other confused-word errors arise from near forms, meanings or grammatical roles. Check the intended idea, the sentence pattern and a dictionary entry before choosing a correction. Sound resemblance alone does not make a replacement appropriate.',
 'Original model error: Please give a pacific reason for changing the meeting. If the writer means an exact reason, specific is intended; pacific concerns peace. Separately, advice is a noun and advise a verb in these models: Bih gave advice; she advised the group. Correcting a word should preserve the intended message rather than merely produce a different grammatical sentence.',
 'State what the writer seems to mean, identify the unsuitable word and propose a context-fitting form. Explain the difference in meaning or function. Mark uncertainty if the intended meaning cannot be established.',[
 F('malapropism','an inappropriate near-sounding substitution for an intended word','Pacific is used where the model intends specific.','Every spelling mistake must be a malapropism.','The taught feature involves an inappropriate sound-related word substitution.'),
 F('meaning distinction','a difference in sense relevant to the intended message','Specific concerns precision; pacific concerns peace.','Near-sounding words always have the same meaning.','Resembling forms can carry different senses.'),
 F('word-class distinction','a grammatical-role difference between confusing forms','Advice is the noun; advise is the verb in the model.','Advice and advise can always exchange sentence roles unchanged.','The sentence needs the appropriate grammatical form.'),
 F('contextual correction','a repair fitting the intended sense and sentence pattern','A request for an exact reason needs specific here.','Any correctly spelled replacement preserves the message.','Correct spelling alone does not ensure intended meaning.')],choose(21,[
 ('The writer wants an exact reason: Please give a pacific reason. Which repair fits?','Please give a specific reason.',['Please give an oceanic reason.','Please give a peaceful reason.','Please give no reason.'],['Oceanic does not mean exact.','Peaceful changes the intended precision to peacefulness.','That reverses the request.'],'Specific expresses the stated intention.'),
 ('Choose the verb: Please ___ the club about the change.','advise',['advice','advisable','adviser'],['Advice is a noun here.','Advisable is an adjective.','Adviser names a person.'],'After please, the request needs the base verb advise.'),
 ('Choose the noun: Bih offered useful ___.','advice',['advise','advisable','advising us'],['Advise is the verb, not the intended noun.','Advisable is adjectival.','That phrase does not fit the stated noun pattern.'],'Advice is the uncountable noun in this use.'),
 ('Choose the form meaning receive: The secretary will ___ the documents.','accept',['except','acceptance','exception'],['Except ordinarily expresses exclusion here, not receipt.','Acceptance is a noun, not the base verb after will.','Exception names an excluded case.'],'The intended action is acceptance, not exclusion.')]),[19,20])

adapt(22,20,'Narrative writing: choices, viewpoint and consequence','draft a coherent narrative in which choices produce an intelligible development','prose, creative scene and retelling','sentence variety and editing',[7,15,20,21],
 'Lower Sixth extension: distinguish telling events in order from developing a narrative. Establish whose experience guides the reader, introduce a meaningful complication and show a choice with a consequence. A flashback may be useful if time relations remain clear. Do not add an unrelated rescue merely to end the piece. The original model and paper task below extend the Form Five narrative foundation; produce a new situation rather than copying its wording.')

adapt(23,11,'Simple, compound and complex sentences','classify clause relationships and revise sentence structure without changing its meaning','conjunctions and coherent narrative','error diagnosis and descriptive control',[12,22],
 'Lower Sixth extension: clause count and dependency determine sentence structure, not length. Bih and Tabe checked and filed the notice can remain a simple sentence despite its coordinated subjects and verbs. Bih checked the notice, but Tabe waited has independent clauses. Because the hall was locked, they waited includes dependency. Vary structure to express time, reason or contrast accurately; do not label every long sentence complex.')

unit(24,'Diagnosing grammatical errors in context','identify a specific error and make a meaning-preserving repair','word roles, clause structure and reference','comparison and descriptive drafting',
 'Editing requires a diagnosis before a correction. Identify the intended meaning and the relevant pattern: agreement, reference, word form or clause boundary. The nearest noun does not necessarily control a verb. A comma alone cannot join independent clauses in the taught formal model. Different acceptable English varieties may use different patterns, so distinguish the specified edited model from a claim that every local use lacks meaning.',
 'Original editing examples: The list of items is ready agrees with list, not items. Bih spoke to Ngozi; the pronoun she may need clarification if either could be meant. We waited because the room was locked expresses a reason. We waited, the room was locked needs a suitable boundary or an explicit connector in this edited model.',
 'Read for meaning, mark the exact faulty relationship and repair only what is needed. Check the whole result for a new error. If more than one repair is possible, state what meaning your chosen connector creates.',[
 F('agreement diagnosis','identifying the grammatical subject controlling the finite verb','The list of items is ready agrees with list.','The nearest plural noun always requires a plural verb.','The head of the subject, not every nearby noun, controls this agreement.'),
 F('reference diagnosis','checking whether a pronoun’s intended referent is clear','Two named people before she may leave the referent uncertain.','Every pronoun has exactly one possible referent in every context.','Context or repetition may be needed to clarify reference.'),
 F('boundary diagnosis','checking how independent clauses are joined','A comma alone between independent clauses creates a comma splice in this model.','Every comma can replace a full stop between independent clauses.','Use a suitable connector, semicolon or full stop for this relationship.'),
 F('meaning-preserving repair','an edit that corrects form without inventing a different message','Because is chosen only when a reason is intended.','Any grammatical connector preserves exactly the same relation.','Different connectors can change time, condition, reason or contrast.')],choose(24,[
 ('Choose the edited agreement: The list of requests ___ ready.','is',['are','be','were being be'],['Requests is inside an of phrase; list is the subject head.','Be alone is not the present finite form needed.','That sequence does not form the intended predicate.'],'The singular head list controls is.'),
 ('Two independent clauses are intended with no causal claim: Bih checked the note, Tabe waited. Which minimal formal repair preserves that?','Bih checked the note; Tabe waited.',['Bih checked the note Tabe waited.','Because Bih checked the note.','Bih checked the note, because Tabe always lied.'],['Removing punctuation leaves a fused sentence.','That leaves only a dependent clause and drops the other event.','The invented cause and lying claim change the message.'],'A semicolon can join related independent clauses without adding a cause.'),
 ('Bih told Ngozi that she would lead. The writer means Ngozi. Which repair makes that reference explicit?','Bih told Ngozi that Ngozi would lead.',['Bih told Ngozi that Bih would lead.','Nobody would lead.','They had never spoken.'],['That selects the other person.','That removes the stated plan.','That contradicts the speech event.'],'Repeating the intended name removes this ambiguity.')]),[10,14,21,23])

unit(25,'Comparatives and superlatives: form and scope','form a comparison and distinguish a pairwise judgement from a group maximum','modifiers and editing','precise descriptive writing',
 'Comparatives relate a quality across a comparison, as in clearer than this version. Superlatives identify an extreme within a stated group, as in the clearest of these drafts. Many short adjectives take er and est; some longer forms use more and most. Irregular patterns include good, better, best. Avoid double marking such as more clearer. A comparative claim must say or imply a sensible comparison basis.',
 'Original model: Draft B is clearer than Draft A for the stated audience. Among the displayed drafts, B is the clearest. These judgements concern a criterion and group; they do not prove B is the best text ever written. More useful is the selected longer-adjective model, while better is the irregular comparison of good.',
 'Identify the quality, comparison set and required degree. Choose the appropriate form, then check than for the comparative model and a clear group for the superlative. Do not combine both methods of marking the same degree.',[
 F('comparative','a form expressing a comparison in degree','Clearer than Draft A compares clarity.','More clearer is the taught edited form.','Do not double-mark this comparative.'),
 F('superlative','a form identifying an extreme within a stated group','The clearest of the displayed drafts refers to that group.','The clearest here proves the best in every possible context.','The claim is limited to its group and criterion.'),
 F('irregular comparison','a degree pattern not formed by simply adding the regular ending','Good has the comparative better in the model.','Gooder is the model comparative of good.','Use the established irregular form.'),
 F('comparison basis','the quality and reference set that make the judgement interpretable','A clarity comparison names the drafts and intended reader.','A comparison never needs a relevant criterion.','The criterion and reference matter to meaning.')],choose(25,[
 ('Choose the edited comparative: This explanation is ___ than that version.','clearer',['more clearer','clearest','most clearer'],['That double-marks the comparative.','The superlative does not fit this than pattern.','That combines incompatible degree marking.'],'Use clearer than in the stated pairwise comparison.'),
 ('Choose the irregular comparative of good for this sentence: Her revised ending is ___ than her first.','better',['gooder','best','most gooder'],['Good uses an irregular pattern.','Best is the superlative, not the comparative here.','That is not the taught edited form.'],'Good, better, best form the model series.'),
 ('Choose the model form: Of the displayed proposals, this is the ___.','most useful',['more useful than','usefuler','more most useful'],['Than requires a completed comparison rather than this group-maximum pattern.','The selected longer-adjective pattern uses more or most.','That double-marks degree.'],'The group maximum uses most useful.'),
 ('Draft B is clearer than A for these readers. What cannot be inferred?','B is the best text for every reader and purpose',['A and B are being compared','Clarity is the named criterion','The claim refers to these readers'],['That pair is explicitly identified.','The word clearer supplies the criterion.','The audience limit is explicit.'],'A contextual comparative does not establish an unlimited superlative.')]),[12,24])

composition(26,'Writing a focused descriptive passage','create an impression through selected sensory detail and coherent organisation','modification, comparison and narrative viewpoint','later extended description and stylistic analysis',
 'Description selects details to create a coherent impression for a reader. Organise attention, for example from entrance to interior or from a broad view to a significant object. Sensory detail should serve the intended mood rather than accumulate unrelated adjectives. Concrete nouns and precise verbs can carry description. A comparison should clarify an impression without making an unsupported literal claim. Avoid shifting viewpoint or time accidentally.',
 ['From the doorway, the reading room looked almost empty. A strip of afternoon light crossed the nearest table, leaving the far shelves in shadow. The open window lifted the edge of a loose page, then let it fall with a soft tap.',
 'Beyond the table, a chair stood angled towards the window. Its worn seat and the small stack of folded notes beside it suggested recent use. I stopped at the threshold; the room seemed quiet rather than abandoned.'],[
 ('controlling impression','the main effect towards which descriptive details contribute','Quiet rather than abandoned gives the model a focused impression.','A description should pursue every possible mood at once.','Selection helps details work towards a coherent effect.'),
 ('spatial organisation','an order guiding attention through a described space','The model moves from doorway to table and far shelves.','Description must list objects in a random order.','A spatial path helps the reader follow attention.'),
 ('sensory detail','a specific impression associated with perception','A loose page falls with a soft tap.','Every sentence needs several unrelated adjectives.','Relevant concrete detail can convey an impression efficiently.'),
 ('qualified interpretation','a judgement limited to what observed detail suggests','The room seems quiet rather than abandoned.','A small observation proves every fact about a place.','The narrator’s impression should not exceed its evidence.')],
 'Describe a familiar shared space at a particular moment for a reader who has never seen it. Establish a viewpoint and a controlling impression, use an intelligible spatial order and select details that support the effect. Create a new passage rather than copying the reading-room model.',[15,22,24,25])

OUT.mkdir(parents=True,exist_ok=True)
(OUT/'sources.json').write_text(json.dumps({'english':{
 'ref':'Original passages, drama scenes, prompts and models; Cambridge English Grammar Today for contextual word functions and determiners; British Council/Macmillan teaching resources for the selected British phonemic model. Five explicitly recorded Form Five foundation extensions retain validated pattern banks.',
 'urls':['https://dictionary.cambridge.org/us/grammar/british-grammar/pronouns_2','https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this','https://www.teachingenglish.org.uk/sites/teacheng/files/TeachingSpeaking_3_sounds_v01.pdf'],
 'checked':'2026-10-24. Conceptual grammar and selected phonemic model checked against institutional resources including indexed passages. All creative and comprehension material is original classroom fiction, not a prescribed text, archive quotation or real school survey. No exam-paper structure or official marking rubric is invented. Teacher review remains necessary.'}},ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
lines=['# Lower Sixth English — learning path','','Each opening gives a measurable end goal, earlier knowledge and next use. All passages are original. Sound work is written preparation, not listening or pronunciation assessment.','','| Row | Topic | Outcome | Builds on | Leads to |','|---|---|---|---|---|']
lines += [f'| {n} | {title} | {goal} | {back} | {onward} |' for n,title,goal,back,onward in sorted(PATH)]
lines += ['','Row 1 diagnostic and row 16 explicit reading/grammar review are excluded under the authoring activity policy despite the parser calling them lessons. Twenty-four teaching drafts remain. Rows 9/11/17/22/23 explicitly extend Form Five foundations 32/7/29/20/11 with new goals, advanced comparison or scope commentary, and connections. Other rows are newly authored.','','Writing rows 9/11/15/22/26 use paper tasks with original models and self-check criteria. Overall destination: read with evidence, preserve meaning when transforming text, and produce coherent original work for a specified purpose.']
(OUT/'LEARNING-PATH.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
(OUT/'TEACHER-REVIEW.md').write_text('''# Lower Sixth English — teacher review

- TR-english-1: Confirm Term One scope and progression against the school’s Advanced English course. Row 1 diagnostic and row 16 explicit review are excluded even though the parser labels every row lesson. No official papers, weighting, word limits or marking scheme are inferred from the diagnostic title.
- TR-english-2: All comprehension, prose, drama and creative models are original classroom material. They are not replacements for prescribed books. Confirm depth of narrator reliability, character, setting, conflict and stage interpretation before classroom approval.
- TR-english-3: Row 8 supplies written sound-symbol preparation using an explicit British dictionary teaching model. Local and other English varieties differ. Teachers must demonstrate and assess actual hearing, articulation, stress and interaction separately. The app does not claim pronunciation mastery from a symbol choice.
- TR-english-4: Row 19 uses the narrow shared-spelling-and-pronunciation homonym convention, while some courses use homonym more broadly. Confirm the local examination convention and accent assumptions for homophones. Do not treat differing dialect pronunciation as absence of communicative ability.
- TR-english-5: Rows 9/11/17/22/23 explicitly extend validated Form Five foundation banks with new goals, connections and a Lower Sixth comparison/scope model. Confirm whether additional course-specific difficulty or genres are required. Writing uses paper prompts/models/checklists, not automatic judgement of originality or quality.
- TR-english-6: Confirm preferred formal-letter layouts, salutation/closing conventions, essay terminology and acceptable alternative structures. The inherited letter pair is a foundation model; teachers should give a fresh task and assess purpose, register and support rather than require memorised wording.
- TR-english-7: Grammar choices target stated edited patterns. Countability, reference, comparison and word class are contextual; some sentences admit other forms when their meanings differ. Confirm accepted alternative repairs and language-variety policy. Malapropism is distinguished from every spelling error.
- TR-english-8: Summary, paraphrase, inference and retelling retain quantifiers, certainty, chronology and causation. Invented trials do not establish real outcomes. Teachers should add authentic texts, acknowledgement conventions and extended evidence questions. Technical checks do not establish exam readiness or actual learning.
''',encoding='utf-8')
assert len(PATH)==24 and {n for n,*_ in PATH}==set(range(2,27))-{16}
